/**
 * Google Drive Connector
 * Provides list, read, and upload operations for Google Drive.
 */

import { google, drive_v3 } from 'googleapis';
import { OAuth2Client } from 'google-auth-library';
import type { ConnectorsConfig } from './config';

let driveClient: drive_v3.Drive | null = null;
let oauth2Client: OAuth2Client | null = null;

export function getAuthClient(config: ConnectorsConfig): OAuth2Client {
  if (!config.googleClientId || !config.googleClientSecret) {
    throw new Error('Google API credentials not configured. Use /connectors-config to set them up.');
  }

  if (!oauth2Client) {
    oauth2Client = new google.auth.OAuth2(
      config.googleClientId,
      config.googleClientSecret,
    );

    if (config.googleAccessToken) {
      oauth2Client.setCredentials({
        access_token: config.googleAccessToken,
        refresh_token: config.googleRefreshToken || undefined,
      });
    } else if (config.googleRefreshToken) {
      oauth2Client.setCredentials({
        refresh_token: config.googleRefreshToken,
      });
    }
  }

  return oauth2Client;
}

export function getDriveClient(config: ConnectorsConfig): drive_v3.Drive {
  if (!driveClient) {
    const auth = getAuthClient(config);
    driveClient = google.drive({ version: 'v3', auth });
  }
  return driveClient;
}

export function resetClients(): void {
  driveClient = null;
  oauth2Client = null;
}

export interface DriveFile {
  id: string;
  name: string;
  mimeType: string;
  size: string;
  modifiedTime: string;
  webViewLink: string;
  parents: string[];
}

export async function listDriveFiles(
  config: ConnectorsConfig,
  query?: string,
  pageSize: number = 50,
): Promise<{ files: DriveFile[]; nextPageToken?: string }> {
  const drive = getDriveClient(config);

  const qParts: string[] = ["trashed = false"];
  if (query) {
    qParts.push(`(name contains '${query.replace(/'/g, "\\'")}' or fullText contains '${query.replace(/'/g, "\\'")}')`);
  }

  const response = await drive.files.list({
    q: qParts.join(' and '),
    pageSize,
    fields: 'nextPageToken, files(id, name, mimeType, size, modifiedTime, webViewLink, parents)',
    orderBy: 'modifiedTime desc',
  });

  return {
    files: (response.data.files || []).map(f => ({
      id: f.id || '',
      name: f.name || '',
      mimeType: f.mimeType || '',
      size: f.size || '0',
      modifiedTime: f.modifiedTime || '',
      webViewLink: f.webViewLink || '',
      parents: f.parents || [],
    })),
    nextPageToken: response.data.nextPageToken || undefined,
  };
}

export async function readDriveFile(
  config: ConnectorsConfig,
  fileId: string,
): Promise<{ name: string; mimeType: string; content: string }> {
  const drive = getDriveClient(config);

  const meta = await drive.files.get({ fileId, fields: 'name, mimeType' });
  const name = meta.data.name || 'unknown';
  const mimeType = meta.data.mimeType || 'unknown';

  // For Google Docs/Sheets/Slides, export as text/plain
  const exportMimeTypes: Record<string, string> = {
    'application/vnd.google-apps.document': 'text/plain',
    'application/vnd.google-apps.spreadsheet': 'text/csv',
    'application/vnd.google-apps.presentation': 'text/plain',
  };

  if (exportMimeTypes[mimeType]) {
    const res = await drive.files.export(
      { fileId, mimeType: exportMimeTypes[mimeType] },
      { responseType: 'text' },
    );
    return { name, mimeType, content: res.data as string };
  }

  // For regular files, download
  const res = await drive.files.get(
    { fileId, alt: 'media' },
    { responseType: 'text' },
  );
  return { name, mimeType, content: res.data as string };
}

export async function uploadToDrive(
  config: ConnectorsConfig,
  filePath: string,
  content: string,
  mimeType: string = 'text/plain',
  parentFolderId?: string,
): Promise<DriveFile> {
  const drive = getDriveClient(config);
  const { Readable } = await import('stream');

  const media = {
    mimeType,
    body: Readable.from([content]),
  };

  const requestBody: any = {
    name: filePath.split('/').pop() || filePath.split('\\').pop() || 'uploaded-file',
  };

  if (parentFolderId) {
    requestBody.parents = [parentFolderId];
  }

  const response = await drive.files.create({
    requestBody,
    media,
    fields: 'id, name, mimeType, size, modifiedTime, webViewLink, parents',
  });

  const f = response.data;
  return {
    id: f.id || '',
    name: f.name || '',
    mimeType: f.mimeType || '',
    size: f.size || '0',
    modifiedTime: f.modifiedTime || '',
    webViewLink: f.webViewLink || '',
    parents: f.parents || [],
  };
}

export async function generateAuthUrl(config: ConnectorsConfig, redirectUri: string): Promise<string> {
  const oauth = getAuthClient(config);
  return oauth.generateAuthUrl({
    access_type: 'offline',
    scope: [
      'https://www.googleapis.com/auth/drive.readonly',
      'https://www.googleapis.com/auth/drive.file',
      'https://www.googleapis.com/auth/gmail.readonly',
    ],
    redirect_uri: redirectUri,
  });
}

export async function exchangeCodeForToken(
  config: ConnectorsConfig,
  code: string,
  redirectUri: string,
): Promise<{ accessToken: string; refreshToken: string }> {
  const oauth = getAuthClient(config);
  const { tokens } = await oauth.getToken({ code, redirect_uri: redirectUri });
  return {
    accessToken: tokens.access_token || '',
    refreshToken: tokens.refresh_token || '',
  };
}

