 * Provides list, search, and read operations for Gmail.
 */

import { google, gmail_v1 } from 'googleapis';
import type { ConnectorsConfig } from './config';
import { getAuthClient } from './drive';

let gmailClient: gmail_v1.Gmail | null = null;

export function getGmailClient(config: ConnectorsConfig): gmail_v1.Gmail {
  if (!gmailClient) {
    const auth = getAuthClient(config);
    gmailClient = google.gmail({ version: 'v1', auth });
  }
  return gmailClient;
