export interface EmailSummary {
  id: string;
  threadId: string;
  subject: string;
  from: string;
  to: string;
  date: string;
  snippet: string;
  labels: string[];
  isUnread: boolean;
}

export interface EmailDetail extends EmailSummary {
  bodyText: string;
  bodyHtml: string;
  cc: string;
  bcc: string;
  attachments: { filename: string; mimeType: string; size: number; attachmentId: string }[];
}

function decodeBase64Url(data: string): string {
  return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
}

function getHeader(headers: gmail_v1.Schema$MessagePartHeader[] | undefined, name: string): string {
  const header = headers?.find(h => h.name?.toLowerCase() === name.toLowerCase());
  return header?.value || '';
}

function parseEmailBody(payload: gmail_v1.Schema$MessagePart, mimeType: 'text/plain' | 'text/html'): string {
  if (payload.mimeType === mimeType && payload.body?.data) {
    return decodeBase64Url(payload.body.data);
  }

  if (payload.parts) {
    for (const part of payload.parts) {
      if (part.mimeType === mimeType && part.body?.data) {
        return decodeBase64Url(part.body.data);
      }
      // Handle multipart/alternative
      if (part.mimeType === 'multipart/alternative' && part.parts) {
        for (const subPart of part.parts) {
          if (subPart.mimeType === mimeType && subPart.body?.data) {
            return decodeBase64Url(subPart.body.data);
          }
        }
      }
    }
  }

  return '';
}

function parseEmailBodyParts(payload: gmail_v1.Schema$MessagePart): { text: string; html: string } {
  return {
    text: parseEmailBody(payload, 'text/plain'),
    html: parseEmailBody(payload, 'text/html'),
  };
}

function listAttachments(payload: gmail_v1.Schema$MessagePart): EmailDetail['attachments'] {
  const attachments: EmailDetail['attachments'] = [];

  function collect(part: gmail_v1.Schema$MessagePart): void {
    if (part.filename && part.body?.attachmentId) {
      attachments.push({
        filename: part.filename,
        mimeType: part.mimeType || 'application/octet-stream',
        size: Number(part.body.size) || 0,
        attachmentId: part.body.attachmentId,
      });
    }
    if (part.parts) {
      part.parts.forEach(collect);
    }
  }

  collect(payload);
  return attachments;
}

export async function listEmails(
  config: ConnectorsConfig,
  options: {
    query?: string;
    maxResults?: number;
    labelIds?: string[];
    pageToken?: string;
  } = {},
): Promise<{ messages: EmailSummary[]; nextPageToken?: string; resultSizeEstimate: number }> {
  const gmail = getGmailClient(config);

  const response = await gmail.users.messages.list({
    userId: 'me',
    q: options.query || undefined,
    maxResults: options.maxResults || 20,
    labelIds: options.labelIds || ['INBOX'],
    pageToken: options.pageToken,
  });

  const messageIds = response.data.messages || [];
  const summaries: EmailSummary[] = [];

  for (const msg of messageIds) {
    if (!msg.id) continue;
    try {
      const detail = await gmail.users.messages.get({
        userId: 'me',
        id: msg.id,
        format: 'metadata',
        metadataHeaders: ['Subject', 'From', 'To', 'Date'],
        fields: 'id,threadId,labelIds,snippet,payload/headers',
      });

      const headers = detail.data.payload?.headers;
      summaries.push({
        id: detail.data.id || '',
        threadId: detail.data.threadId || '',
        subject: getHeader(headers, 'Subject'),
        from: getHeader(headers, 'From'),
        to: getHeader(headers, 'To'),
        date: getHeader(headers, 'Date'),
        snippet: detail.data.snippet || '',
        labels: detail.data.labelIds || [],
        isUnread: (detail.data.labelIds || []).includes('UNREAD'),
      });
    } catch {
      // Skip individual message errors
    }
  }

  return {
    messages: summaries,
    nextPageToken: response.data.nextPageToken || undefined,
    resultSizeEstimate: response.data.resultSizeEstimate || 0,
  };
}

export async function readEmail(
  config: ConnectorsConfig,
  emailId: string,
): Promise<EmailDetail> {
  const gmail = getGmailClient(config);

  const detail = await gmail.users.messages.get({
    userId: 'me',
    id: emailId,
    format: 'full',
  });

  const payload = detail.data.payload!;
  const headers = payload.headers;
  const bodies = parseEmailBodyParts(payload);

  return {
    id: detail.data.id || '',
    threadId: detail.data.threadId || '',
    subject: getHeader(headers, 'Subject'),
    from: getHeader(headers, 'From'),
    to: getHeader(headers, 'To'),
    date: getHeader(headers, 'Date'),
    snippet: detail.data.snippet || '',
    labels: detail.data.labelIds || [],
    isUnread: (detail.data.labelIds || []).includes('UNREAD'),
    bodyText: bodies.text,
    bodyHtml: bodies.html,
    cc: getHeader(headers, 'Cc'),
    bcc: getHeader(headers, 'Bcc'),
    attachments: listAttachments(payload),
  };
}

export async function searchEmails(
  config: ConnectorsConfig,
  searchQuery: string,
  maxResults: number = 20,
): Promise<{ messages: EmailSummary[]; nextPageToken?: string; resultSizeEstimate: number }> {
  return listEmails(config, { query: searchQuery, maxResults });
}

/**
 * Local File System Connector
 * Browse directories and read files anywhere on the system.
 */

import { readdirSync, statSync, readFileSync } from 'fs';
import { join, resolve, normalize, isAbsolute } from 'path';
import { homedir } from 'os';

export interface FsEntry {
  name: string;
  path: string;
  type: 'file' | 'directory' | 'symlink' | 'unknown';
  size: number;
  modifiedTime: string;
}

export function sanitizePath(rawPath: string): string {
  // Expand ~ to home directory
  let sanitized = rawPath;
  if (sanitized.startsWith('~')) {
    sanitized = join(homedir(), sanitized.slice(1));
  }
  // Normalize and resolve
  sanitized = normalize(sanitized);
  if (!isAbsolute(sanitized)) {
    sanitized = resolve(sanitized);
  }
  return sanitized;
}

export async function browseDirectory(
  dirPath: string,
): Promise<{ path: string; entries: FsEntry[] }> {
  const absolutePath = sanitizePath(dirPath);

  const stat = statSync(absolutePath);
  if (!stat.isDirectory()) {
    throw new Error(`Not a directory: ${absolutePath}`);
  }

  const dirents = readdirSync(absolutePath, { withFileTypes: true });

  const entries: FsEntry[] = [];
  for (const entry of dirents) {
    const fullPath = join(absolutePath, entry.name);
    try {
      const entryStat = statSync(fullPath);
      entries.push({
        name: entry.name,
        path: fullPath,
        type: entry.isDirectory() ? 'directory'
          : entry.isSymbolicLink() ? 'symlink'
          : entry.isFile() ? 'file'
          : 'unknown',
        size: entryStat.size,
        modifiedTime: entryStat.mtime.toISOString(),
      });
    } catch {
      entries.push({
        name: entry.name,
        path: fullPath,
        type: 'unknown',
        size: 0,
        modifiedTime: '',
      });
    }
  }

  // Sort: directories first, then files, both alphabetically
  entries.sort((a, b) => {
    if (a.type === 'directory' && b.type !== 'directory') return -1;
    if (a.type !== 'directory' && b.type === 'directory') return 1;
    return a.name.localeCompare(b.name);
  });

  return { path: absolutePath, entries };
}

export async function readFileContent(
  filePath: string,
  maxSizeBytes: number = 500 * 1024, // 500KB default
): Promise<{ path: string; content: string; truncated: boolean; size: number }> {
  const absolutePath = sanitizePath(filePath);

  const stat = statSync(absolutePath);
  if (!stat.isFile()) {
    throw new Error(`Not a file: ${absolutePath}`);
  }

  const shouldTruncate = stat.size > maxSizeBytes;
  const content = readFileSync(absolutePath, 'utf-8');

  return {
    path: absolutePath,
    content: shouldTruncate ? content.slice(0, maxSizeBytes) : content,
    truncated: shouldTruncate,
    size: stat.size,
  };
}

export function formatSize(bytes: number): string {
  if (bytes === 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  const size = (bytes / Math.pow(1024, i)).toFixed(i >= 2 ? 2 : 1);
  return `${size} ${units[i]}`;
}

