      <div className="flex gap-2">
        <Button onClick={handleAuth}>Generate Auth URL</Button>
      </div>

      <Input
        label="Auth Code or Redirect URL"
        value={config?.authCode || ''}
        onChange={(e) => updateField('authCode', e.target.value)}
