/**
 * Connectors Extension for AiderDesk
 *
 * Provides connectors for:
 * - Google Drive (list, read, upload)
 * - Gmail (list, search, read)
 * - Local File System (browse, read)
 *
 * Exposes both slash commands and agent-callable tools.
 */

import { readFileSync } from 'fs';
import { join } from 'path';
import { z } from 'zod';

import type {
  Extension,
  ExtensionContext,
  CommandDefinition,
  ToolDefinition,
} from '@aiderdesk/extensions';

import { loadConfig, saveConfig } from './config';
import type { ConnectorsConfig } from './config';

import {
  listDriveFiles,
  readDriveFile,
  uploadToDrive,
  generateAuthUrl,
  exchangeCodeForToken,
  resetClients,
} from './drive';

import { listEmails, readEmail, searchEmails, resetGmailClient } from './gmail';
import { browseDirectory, readFileContent, formatSize } from './filesystem';

// ─── Helper: build a simple text table from array of objects ───

function tableFromArray(rows: Record<string, string>[], columns: string[]): string {
  if (rows.length === 0) return 'No results.';

  const colWidths: Record<string, number> = {};
  for (const col of columns) {
    colWidths[col] = col.length;
    for (const row of rows) {
      colWidths[col] = Math.max(colWidths[col], (row[col] || '').length);
    }
  }

  const header = columns.map(c => c.padEnd(colWidths[c])).join('  ');
  const sep = columns.map(c => '-'.repeat(colWidths[c])).join('  ');
  const body = rows.map(r => columns.map(c => (r[c] || '').padEnd(colWidths[c])).join('  ')).join('\n');

  return `${header}\n${sep}\n${body}`;
}

// ─── Extension Class ───

export default class ConnectorsExtension implements Extension {
  static metadata = {
    name: 'Connectors',
    version: '1.0.0',
    description: 'Google Drive, Gmail, and local file system connectors with commands and agent tools',
    author: 'AiderDesk',
    capabilities: ['commands', 'tools', 'config'],
  };

  private config: ConnectorsConfig = {
    googleClientId: '',
    googleClientSecret: '',
    googleRefreshToken: '',
    googleAccessToken: '',
  };

  async onLoad(context: ExtensionContext): Promise<void> {
    this.config = await loadConfig();
    context.log('Connectors extension loaded', 'info');
  }

  async onUnload(): Promise<void> {
    resetClients();
    resetGmailClient();
  }

  // ─── Config Methods ───

  getConfigComponent(_context: ExtensionContext): string | undefined {
    return readFileSync(join(__dirname, './ConfigComponent.jsx'), 'utf-8');
  }

  async getConfigData(_context: ExtensionContext): Promise<unknown> {
    return { ...this.config };
  }

  async saveConfigData(configData: unknown, _context: ExtensionContext): Promise<unknown> {
    const merged = { ...this.config, ...(configData as Partial<ConnectorsConfig>) };
    // Remove transient authCode field from persisted config
    delete (merged as any).authCode;
    this.config = merged;
    await saveConfig(this.config);
    resetClients();
    resetGmailClient();
    return this.config;
  }

  // ─── Commands ───

  getCommands(_context: ExtensionContext): CommandDefinition[] {
    return [
      // ── Drive Commands ──

      {
        name: 'drive-list',
        description: 'List files in Google Drive',
        arguments: [
          { description: 'Optional search query', required: false },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const { files } = await listDriveFiles(this.config, args[0] || undefined, 30);
            const rows = files.map(f => ({
              Name: f.name.length > 40 ? f.name.slice(0, 37) + '...' : f.name,
              Type: f.mimeType.split('.').pop() || f.mimeType,
              Size: f.size === '0' ? '-' : formatSize(Number(f.size)),
              ID: f.id,
              Modified: f.modifiedTime ? f.modifiedTime.slice(0, 10) : '-',
            }));

            const output = files.length === 0
              ? 'No files found in Google Drive.'
              : `**Google Drive** (${files.length} files)\n\`\`\`\n${tableFromArray(rows, ['Name', 'Type', 'Size', 'Modified', 'ID'])}\n\`\`\``;

            taskCtx?.addLogMessage('info', output);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Drive list failed: ${e.message}`);
          }
        },
      },

      {
        name: 'drive-read',
        description: 'Read a file from Google Drive by ID',
        arguments: [
          { description: 'Google Drive file ID', required: true },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const result = await readDriveFile(this.config, args[0]);
            const truncated = context.truncateToolResult
              ? await context.truncateToolResult(result.content, 500, 100)
              : result.content.slice(0, 50000);

            taskCtx?.addLogMessage('info',
              `**${result.name}** (${result.mimeType})\n\`\`\`\n${truncated}\n\`\`\``);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Drive read failed: ${e.message}`);
          }
        },
      },

      {
        name: 'drive-upload',
        description: 'Upload a file to Google Drive',
        arguments: [
          { description: 'Local file path to upload', required: true },
          { description: 'Optional parent folder ID', required: false },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const { content } = await readFileContent(args[0]);
            const result = await uploadToDrive(this.config, args[0], content, 'text/plain', args[1] || undefined);
            taskCtx?.addLogMessage('info',
              `Uploaded: **${result.name}** (${result.id})\n[Open in Drive](${result.webViewLink})`);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Drive upload failed: ${e.message}`);
          }
        },
      },

      // ── Gmail Commands ──

      {
        name: 'gmail-list',
        description: 'List recent emails from Gmail inbox',
        arguments: [
          { description: 'Optional search/filter query (e.g. "from:example.com")', required: false },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const query = args[0] || undefined;
            const result = query
              ? await searchEmails(this.config, query, 20)
              : await listEmails(this.config, { maxResults: 20 });

            const rows = result.messages.map(m => ({
              From: m.from.length > 25 ? m.from.slice(0, 22) + '...' : m.from,
              Subject: m.subject.length > 40 ? m.subject.slice(0, 37) + '...' : m.subject,
              Date: m.date,
              ID: m.id,
              Status: m.isUnread ? 'UNREAD' : 'read',
            }));

            const output = result.messages.length === 0
              ? 'No emails found.'
              : `**Gmail** (${result.messages.length} of ~${result.resultSizeEstimate})\n\`\`\`\n${tableFromArray(rows, ['From', 'Subject', 'Date', 'Status', 'ID'])}\n\`\`\``;

            taskCtx?.addLogMessage('info', output);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Gmail list failed: ${e.message}`);
          }
        },
      },

      {
        name: 'gmail-read',
        description: 'Read a specific email by ID',
        arguments: [
          { description: 'Email message ID', required: true },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const email = await readEmail(this.config, args[0]);
            const truncated = context.truncateToolResult
              ? await context.truncateToolResult(email.bodyText, 500, 100)
              : email.bodyText.slice(0, 50000);

            let output = [
              `**From:** ${email.from}`,
              `**To:** ${email.to}`,
              email.cc ? `**Cc:** ${email.cc}` : '',
              `**Date:** ${email.date}`,
              `**Subject:** ${email.subject}`,
              `**Labels:** ${email.labels.join(', ')}`,
              '',
              truncated,
            ].filter(Boolean).join('\n');

            if (email.attachments.length > 0) {
              output += '\n\n**Attachments:**\n' + email.attachments.map(
                a => `- ${a.filename} (${formatSize(a.size)}, ${a.mimeType}) [ID: ${a.attachmentId}]`
              ).join('\n');
            }

            taskCtx?.addLogMessage('info', output);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Gmail read failed: ${e.message}`);
          }
        },
      },

      {
        name: 'gmail-search',
        description: 'Search Gmail with a query',
        arguments: [
          { description: 'Gmail search query (supports Gmail search operators)', required: true },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const result = await searchEmails(this.config, args[0], 20);

            const rows = result.messages.map(m => ({
              From: m.from.length > 25 ? m.from.slice(0, 22) + '...' : m.from,
              Subject: m.subject.length > 40 ? m.subject.slice(0, 37) + '...' : m.subject,
              Date: m.date,
              ID: m.id,
            }));

            const output = result.messages.length === 0
              ? `No emails found for query: "${args[0]}"`
              : `**Gmail Search:** "${args[0]}" (${result.messages.length} results)\n\`\`\`\n${tableFromArray(rows, ['From', 'Subject', 'Date', 'ID'])}\n\`\`\``;

            taskCtx?.addLogMessage('info', output);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Gmail search failed: ${e.message}`);
          }
        },
      },

      // ── File System Commands ──

      {
        name: 'fs-browse',
        description: 'Browse a directory on the local file system',
        arguments: [
          { description: 'Directory path (use ~ for home, absolute or relative)', required: true },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const { path, entries } = await browseDirectory(args[0]);

            const rows = entries.slice(0, 100).map(e => ({
              Type: e.type === 'directory' ? '[DIR] ' : e.type === 'symlink' ? '[LNK] ' : '[FILE]',
              Name: e.name.length > 50 ? e.name.slice(0, 47) + '...' : e.name,
              Size: e.type === 'directory' ? '-' : formatSize(e.size),
              Modified: e.modifiedTime ? e.modifiedTime.slice(0, 10) : '-',
            }));

            const header = `**${path}** (${entries.length} entries${entries.length > 100 ? ', showing first 100' : ''})\n`;
            const table = entries.length > 0
              ? `\`\`\`\n${tableFromArray(rows, ['Type', 'Name', 'Size', 'Modified'])}\n\`\`\``
              : 'Directory is empty.';

            taskCtx?.addLogMessage('info', header + table);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Browse failed: ${e.message}`);
          }
        },
      },

      {
        name: 'fs-read',
        description: 'Read a file from the local file system',
        arguments: [
          { description: 'File path (use ~ for home, absolute or relative)', required: true },
        ],
        execute: async (args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          try {
            const result = await readFileContent(args[0]);
            const truncated = context.truncateToolResult
              ? await context.truncateToolResult(result.content, 500, 100)
              : result.content.slice(0, 50000);

            taskCtx?.addLogMessage('info',
              `**${result.path}** (${formatSize(result.size)}${result.truncated ? ', truncated' : ''})\n\`\`\`\n${truncated}\n\`\`\``);
          } catch (e: any) {
            taskCtx?.addLogMessage('error', `Read failed: ${e.message}`);
          }
        },
      },

      {
        name: 'connectors-config',
        description: 'Show current connector configuration status',
        execute: async (_args: string[], context: ExtensionContext) => {
          const taskCtx = context.getTaskContext();
          const lines = [
            '**Connectors Configuration**',
            '',
            `Google Drive: ${this.config.googleClientId ? '✓ Configured' : '✗ Not configured'}`,
            `Google Auth:  ${this.config.googleAccessToken ? '✓ Authenticated' : '✗ Not authenticated'}`,
            `File System:  ✓ Always available`,
            '',
            'Use the extension settings (gear icon) to configure Google API credentials.',
          ];
          taskCtx?.addLogMessage('info', lines.join('\n'));
        },
      },
    ];
  }

  // ─── Agent Tools ───

  getTools(_context: ExtensionContext): ToolDefinition[] {
    const config = this.config;

    return [
      // ── Drive Tools ──

      {
        name: 'drive-list-files',
        description: 'List files from Google Drive. Returns file name, type, size, ID, and modification date.',
        inputSchema: z.object({
          query: z.string().optional().describe('Optional search query to filter files by name or content'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`drive-list-files called with query: ${input.query || 'none'}`, 'debug');
          const { files } = await listDriveFiles(config, input.query || undefined, 30);
          return files;
        },
      },

      {
        name: 'drive-read-file',
        description: 'Read the content of a Google Drive file by its ID. Works with Google Docs, Sheets (exported as CSV), and regular files.',
        inputSchema: z.object({
          fileId: z.string().describe('The Google Drive file ID to read'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`drive-read-file called for: ${input.fileId}`, 'debug');
          const result = await readDriveFile(config, input.fileId);
          return { name: result.name, mimeType: result.mimeType, content: result.content };
        },
      },

      {
        name: 'drive-upload-file',
        description: 'Upload content to Google Drive as a new file.',
        inputSchema: z.object({
          fileName: z.string().describe('Name for the file in Drive'),
          content: z.string().describe('Text content to upload'),
          mimeType: z.string().optional().describe('MIME type (default: text/plain)'),
          parentFolderId: z.string().optional().describe('Optional parent folder ID in Drive'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`drive-upload-file called: ${input.fileName}`, 'debug');
          const result = await uploadToDrive(
            config, input.fileName, input.content,
            input.mimeType || 'text/plain',
            input.parentFolderId || undefined,
          );
          return result;
        },
      },

      // ── Gmail Tools ──

      {
        name: 'gmail-list-emails',
        description: 'List recent emails from Gmail inbox. Returns sender, subject, date, and ID.',
        inputSchema: z.object({
          query: z.string().optional().describe('Optional Gmail search query (supports Gmail search operators like "from:", "subject:", etc.)'),
          maxResults: z.number().optional().describe('Maximum number of emails (default: 20)'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`gmail-list-emails called with query: ${input.query || 'none'}`, 'debug');
          const result = input.query
            ? await searchEmails(config, input.query, input.maxResults || 20)
            : await listEmails(config, { maxResults: input.maxResults || 20 });
          return result;
        },
      },

      {
        name: 'gmail-read-email',
        description: 'Read a specific email by its ID. Returns full email including body text, headers, and attachments.',
        inputSchema: z.object({
          emailId: z.string().describe('The Gmail message ID to read'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`gmail-read-email called for: ${input.emailId}`, 'debug');
          const email = await readEmail(config, input.emailId);
          return {
            id: email.id,
            threadId: email.threadId,
            subject: email.subject,
            from: email.from,
            to: email.to,
            cc: email.cc,
            bcc: email.bcc,
            date: email.date,
            labels: email.labels,
            bodyText: email.bodyText,
            attachments: email.attachments,
          };
        },
      },

      {
        name: 'gmail-search-emails',
        description: 'Search Gmail using Gmail search operators (e.g., "from:example.com", "has:attachment", "newer_than:7d").',
        inputSchema: z.object({
          searchQuery: z.string().describe('Gmail search query with search operators'),
          maxResults: z.number().optional().describe('Maximum results (default: 20)'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`gmail-search-emails called: ${input.searchQuery}`, 'debug');
          const result = await searchEmails(config, input.searchQuery, input.maxResults || 20);
          return result;
        },
      },

      // ── File System Tools ──

      {
        name: 'fs-browse-directory',
        description: 'Browse a directory on the local file system. Returns entries with name, type, size, and modification time.',
        inputSchema: z.object({
          path: z.string().describe('Directory path. Use ~ for home directory, or provide an absolute path.'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`fs-browse-directory called: ${input.path}`, 'debug');
          const result = await browseDirectory(input.path);
          return { path: result.path, entries: result.entries };
        },
      },

      {
        name: 'fs-read-file',
        description: 'Read a file from anywhere on the local file system. Returns content, size, and whether it was truncated.',
        inputSchema: z.object({
          path: z.string().describe('Absolute file path. Use ~ for home directory.'),
          maxSizeKB: z.number().optional().describe('Maximum size in KB to read (default: 500)'),
        }),
        execute: async (input, _signal, ctx) => {
          ctx.log(`fs-read-file called: ${input.path}`, 'debug');
          const maxBytes = (input.maxSizeKB || 500) * 1024;
          const result = await readFileContent(input.path, maxBytes);
          return { path: result.path, content: result.content, truncated: result.truncated, size: result.size };
        },
      },
    ];
  }

  // ─── UI Component Actions ───

  async executeUIExtensionAction(
    _componentId: string,
    action: string,
    args: unknown[],
    _context: ExtensionContext,
  ): Promise<unknown> {
    if (action === 'generate-auth-url') {
      const url = await generateAuthUrl(this.config, 'http://localhost');
      return { url };
    }

    if (action === 'exchange-code') {
      const codeInput = args[0] as string;

      // Extract code from redirect URL if needed
      let code = codeInput;
      if (codeInput.includes('code=')) {
        const url = new URL(codeInput);
        code = url.searchParams.get('code') || codeInput;
      }

      const tokens = await exchangeCodeForToken(this.config, code, 'http://localhost');
      this.config.googleAccessToken = tokens.accessToken;
      this.config.googleRefreshToken = tokens.refreshToken;
      await saveConfig(this.config);
      resetClients();
      resetGmailClient();
      return { success: true };
    }

    throw new Error(`Unknown action: ${action}`);
  }
}

