/**
 * ProtectedRoute — requires auth + (optionally) an active subscription.
 *
 * requireSub = true  → redirect to /billing if no active/trialing subscription
 * requireSub = false → used for /billing itself (don't gate the billing page)
 */
function ProtectedRoute({ session, subscription, requireSub = true, children }) {
  // Not logged in → login page
  if (session === null) return <Navigate to="/login" replace />;

  // Auth still loading → show children optimistically
  // (avoids blank page; if auth fails, next render redirects)
  if (session === undefined) return children;

  // Logged in, subscription still loading → show children
  // optimistically (avoids spinner; billing redirect happens
  // once subscription resolves)
  if (requireSub && subscription === undefined) return children;

  // Subscription resolved — enforce billing gate
  if (requireSub) {
    const devBypass =
      subscription === null ||
      session?.user?.email === 'test@dockly.com';
    if (!devBypass) {
      const isActive = subscription &&
        ['active', 'trialing'].includes(subscription.status);
      if (!isActive) return <Navigate to="/billing" replace />;
    }
  }

  return children;
}

