import { createClient } from '@supabase/supabase-js';

const url = process.env.REACT_APP_SUPABASE_URL;
const key = process.env.REACT_APP_SUPABASE_ANON_KEY;

// Use placeholder values so the module loads even when env vars are missing.
// App.js checks for missing config and renders an error screen before any
// Supabase calls are made.
export const supabase = createClient(
  url  || 'https://placeholder.supabase.co',
  key  || 'placeholder-anon-key',
  {
    auth: {
      autoRefreshToken: true,
      persistSession: true,
      detectSessionInUrl: true,
      // Truthy no-op lock: bypasses navigator.locks (whose LockManager can
      // deadlock/hang getSession — and since every authed request resolves its
      // token via getSession, that hang surfaces as stuck requests/spinners).
      // Safe for Dockly's single-user sessions; the only thing it gives up is
      // multi-tab token-refresh serialization.
      lock: async (_name, _acquireTimeout, fn) => fn(),
    },
  }
);

export const supabaseConfigured = !!(url && key);

// ── Thin anon query builder ────────────────────────────────────────────────
// Mirrors the subset of the Supabase query API used in DriverCheckIn and
// DeliveryCheckIn for public load lookups and status updates.
//
// Using a second createClient() triggers "Multiple GoTrueClient instances"
// warnings and auth conflicts because both clients share the same localStorage
// auth slot. This fetch-based builder achieves the same result — unauthenticated
// REST calls with just the anon key — without creating any GoTrueClient at all.
//
// Supported chain patterns (matching actual usage):
//   supabaseAnon.from(t).select(cols).eq(col, val).single()
//   supabaseAnon.from(t).update(obj).eq(col, val).select(returnCols)
//   supabaseAnon.from(t).update(obj).eq(col, val)
//   supabaseAnon.from(t).insert(obj).select(cols).single()
//   supabaseAnon.from(t).insert(obj)
// ──────────────────────────────────────────────────────────────────────────

const _base = url || 'https://placeholder.supabase.co';
const _key  = key || 'placeholder-anon-key';

function makeAnonBuilder(table) {
  let method     = 'GET';
  let bodyObj    = null;
  let fetchCols  = '*';
  let returnCols = null;
  let filters    = [];
  let singleMode = false;
  let maybeMode  = false;

  const b = {
    select(cols) {
      // select() before update/insert → columns to fetch
      // select() after  update/insert → columns to return
      if (method === 'PATCH' || method === 'POST') returnCols = cols;
      else fetchCols = cols;
      return b;
    },
    insert(obj) {
      method  = 'POST';
      bodyObj = obj;
      return b;
    },
    update(obj) {
      method  = 'PATCH';
      bodyObj = obj;
      return b;
    },
    eq(col, val) {
      filters.push([col, val]);
      return b;
    },
    single() {
      singleMode = true;
      return b;
    },
    maybeSingle() {
      singleMode = true;
      maybeMode  = true;
      return b;
    },
    // Make the builder thenable so it can be awaited directly
    then(onFulfilled, onRejected) { return _run().then(onFulfilled, onRejected); },
    catch(onRejected)             { return _run().catch(onRejected); },
    finally(onFinally)            { return _run().finally(onFinally); },
  };

  async function _run() {
    const params = new URLSearchParams();
    filters.forEach(([col, val]) => params.set(col, `eq.${val}`));

    if (method === 'GET')                     params.set('select', fetchCols);
    if (method === 'PATCH' && returnCols)     params.set('select', returnCols);

    const headers = {
      'Content-Type': 'application/json',
      'apikey':        _key,
      'Authorization': `Bearer ${_key}`,
      'Accept':        'application/json',
    };

    if (method === 'PATCH' || method === 'POST') {
      headers['Prefer'] = returnCols ? 'return=representation' : 'return=minimal';
    }

    let res;
    try {
      res = await fetch(`${_base}/rest/v1/${table}?${params}`, {
        method,
        headers,
        body: bodyObj ? JSON.stringify(bodyObj) : undefined,
      });
    } catch (networkErr) {
      return { data: null, error: { message: networkErr.message } };
    }

    // PATCH/POST with no return columns — just report success/failure
    if ((method === 'PATCH' || method === 'POST') && !returnCols) {
      if (!res.ok) {
        const err = await res.json().catch(() => ({ message: 'Update failed' }));
        return { data: null, error: err };
      }
      return { data: null, error: null };
    }

    const json = await res.json().catch(() => null);
    if (!res.ok) return { data: null, error: json ?? { message: 'Request failed' } };

    if (singleMode) {
      const row = Array.isArray(json) ? (json[0] ?? null) : json;
      if (!row) {
        // maybeSingle() → null is not an error; single() → error
        if (maybeMode) return { data: null, error: null };
        return { data: null, error: { message: 'Not found', code: 'PGRST116' } };
      }
      return { data: row, error: null };
    }

    return { data: json, error: null };
  }

  return b;
}

