// Keeps the global audio store's userId in sync with auth so tracking, resume
// and preferences attach to the right member regardless of which page is open.
function PlayerUserSync() {
  const { user } = useAuth()
  useEffect(() => { setPlayerUser(user?.id ?? null) }, [user?.id])
  return null
}

// `/` resolves differently depending on auth state — public visitors see the
// marketing landing, pending/denied users hit their respective screens, and
// approved members see the library home.
//
// We intentionally do NOT gate on `loading` here. While auth is resolving,
// `user` is null, so unauthenticated users (the common case on production)
// see the Landing page immediately with no blank flash. Once the session
// check completes and a user is found, React re-renders and routes them to
// the correct screen. The brief Landing→Home flash for logged-in users is
// imperceptible and far better than returning null (blank page).
function RootRouter() {
  const { user } = useAuth()
  if (!user) return <Landing />
  if (user.status === 'pending') return <Navigate to="/pending" replace />
  if (user.status === 'denied') return <Navigate to="/denied" replace />
  return <Home />
}

