import { useSyncExternalStore } from 'react'
import { supabase, isSupabaseConfigured } from './supabase'
import { DEMO_USERS } from '../data/seed'
import { getInvite, markInviteAccepted } from './invites'
import { createRequest } from './requests'

// ───────────────────────────────────────────────────────────────────────────
// Bulletproof auth — module-level singleton store, no React Context/Provider.
//
// Why a module singleton instead of a Provider: useAuth() is consumed by 16
// components. A single store means ONE getSession call, ONE auth listener, and
// ONE profile fetch shared by all of them — no inconsistency, no duplicate work.
// Components subscribe via useSyncExternalStore.
//
// THE BUG THIS FIXES: the previous code called `await supabase.from('profiles')`
// directly inside the onAuthStateChange callback. The Supabase auth client holds
// an internal lock during that callback; the .from() query tries to acquire the
// same lock to attach the access token → DEADLOCK → hangs forever (exactly the
// "200 token returned but app hangs" symptom, regardless of RLS). The fix is to
// DEFER every Supabase data call out of the callback with setTimeout(0), plus
// hard timeouts so nothing can ever hang.
//
// user shape: { id, email, full_name, phone, connection_to_shul, tier, status }
// tier   ∈ 'member' | 'admin'
// status ∈ 'pending' | 'approved' | 'denied'
// ───────────────────────────────────────────────────────────────────────────

const USERS_KEY   = 'ahavasolam-library:demo-users'
const SESSION_KEY = 'ahavasolam-library:demo-session'
const PROFILE_TIMEOUT_MS = 5000

// Debug logger disabled: it was logging user ids, emails and session details to
// the browser console in production. Kept as a no-op so call sites stay inert.
const log = () => {}

// ─── store ─────────────────────────────────────────────────────────────────
let state = { user: null, loading: true }
const listeners = new Set()

function setState(patch) {
  state = { ...state, ...patch }
  for (const l of listeners) l()
}
function subscribe(cb) {
  listeners.add(cb)
  return () => listeners.delete(cb)
}
function getSnapshot() {
  return state
}

// ─── demo-mode helpers ───────────────────────────────────────────────────────
export function loadDemoUsers() {
  try {
    const raw = localStorage.getItem(USERS_KEY)
    if (raw) return JSON.parse(raw)
  } catch { /* ignore */ }
  localStorage.setItem(USERS_KEY, JSON.stringify(DEMO_USERS))
  return [...DEMO_USERS]
}
export function saveDemoUsers(users) {
  localStorage.setItem(USERS_KEY, JSON.stringify(users))
}

function toUser(authUser, profile) {
  return {
    id: authUser.id,
    email: authUser.email,
    full_name: profile?.full_name ?? '',
    phone: profile?.phone ?? '',
    connection_to_shul: profile?.connection_to_shul ?? '',
    tier: profile?.tier ?? 'member',
    status: profile?.status ?? 'pending',
  }
}
function publicUser(u) {
  if (!u) return null
  return {
    id: u.id,
    email: u.email,
    full_name: u.full_name ?? '',
    phone: u.phone ?? '',
    connection_to_shul: u.connection_to_shul ?? '',
    tier: u.tier ?? 'member',
    status: u.status ?? 'pending',
  }
}

// Fetch the profile row. ALWAYS resolves (never hangs): a 5s timeout and full
// try/catch guarantee we return a usable user object with safe defaults rather
// than blocking. Exported so Login.jsx can fetch + log explicitly if it wants.
export async function fetchProfile(authUser) {
  if (!authUser) return null
  log('fetchProfile: start for', authUser.id)
  try {
    const query = supabase
      .from('profiles')
      .select('full_name, phone, connection_to_shul, tier, status')
      .eq('id', authUser.id)
      .maybeSingle()

    const { data, error } = await Promise.race([
      query,
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error('profile fetch timed out')), PROFILE_TIMEOUT_MS),
      ),
    ])

    if (error) {
      log('fetchProfile: query error —', error.message, '(using defaults)')
      return toUser(authUser, null)
    }
    if (!data) {
      log('fetchProfile: no profile row found (using defaults: status=pending)')
      return toUser(authUser, null)
    }
    log('fetchProfile: ok —', { tier: data.tier, status: data.status })
    return toUser(authUser, data)
  } catch (err) {
    log('fetchProfile: FAILED/timeout —', err.message, '(using defaults)')
    return toUser(authUser, null)
  }
}

// ─── one-time init ───────────────────────────────────────────────────────────
let initialized = false
function initAuth() {
  if (initialized) return
  initialized = true

  // Demo mode: read the localStorage session synchronously, done.
  if (!isSupabaseConfigured) {
    log('init: demo mode (no Supabase keys)')
    try {
      const email = localStorage.getItem(SESSION_KEY)
      if (email) {
        const found = loadDemoUsers().find((u) => u.email === email)
        if (found) {
          setState({ user: publicUser(found), loading: false })
          return
        }
      }
    } catch { /* ignore */ }
    setState({ user: null, loading: false })
    return
  }

  log('init: supabase mode')

  // Hard safety net: never let `loading` stay true beyond the timeout.
  const safety = setTimeout(() => {
    if (state.loading) {
      log('init: GLOBAL TIMEOUT — forcing loading=false')
      setState({ loading: false })
    }
  }, PROFILE_TIMEOUT_MS + 1000)

  // 1) Initial session check on mount.
  supabase.auth.getSession()
    .then(async ({ data: { session } }) => {
      log('init: getSession ->', session?.user ? `user ${session.user.id}` : 'no session')
      if (!session?.user) {
        setState({ user: null, loading: false })
        return
      }
      const u = await fetchProfile(session.user)
      setState({ user: u, loading: false })
      clearTimeout(safety)
    })
    .catch((err) => {
      log('init: getSession FAILED —', err.message)
      setState({ user: null, loading: false })
    })

  // 2) Listen for all future auth changes (sign-in, sign-out, token refresh).
  //    CRITICAL: do NOT await Supabase data calls synchronously in here — that
  //    deadlocks. Defer the profile fetch with setTimeout(0) to escape the lock.
  supabase.auth.onAuthStateChange((event, session) => {
    log('onAuthStateChange:', event, session?.user ? `user ${session.user.id}` : 'no session')
    if (!session?.user) {
      setState({ user: null, loading: false })
      return
    }
    setTimeout(async () => {
      const u = await fetchProfile(session.user)
      setState({ user: u, loading: false })
    }, 0)
  })
}

// Initialize as soon as this module is imported (before any component renders).
initAuth()

// ─── actions ─────────────────────────────────────────────────────────────────
export async function signIn(email, password) {
  log('signIn: start')
  if (!isSupabaseConfigured) {
    const found = loadDemoUsers().find(
      (u) => u.email.toLowerCase() === email.trim().toLowerCase() && u.password === password,
    )
    if (!found) throw new Error('Invalid email or password.')
    localStorage.setItem(SESSION_KEY, found.email)
    setState({ user: publicUser(found), loading: false })
    log('signIn: demo user set')
    return
  }
  const { error } = await supabase.auth.signInWithPassword({ email, password })
  if (error) {
    log('signIn: signInWithPassword error —', error.message)
    throw error
  }
  log('signIn: password OK — onAuthStateChange will populate user')
  // onAuthStateChange fires and sets the user; Login.jsx watches `user`.
}

export async function signOut() {
  log('signOut')
  if (!isSupabaseConfigured) {
    localStorage.removeItem(SESSION_KEY)
    setState({ user: null, loading: false })
    return
  }
  try {
    await supabase.auth.signOut()
  } catch (err) {
    log('signOut: error —', err.message)
  }
  setState({ user: null, loading: false })
}

export async function requestAccess(fields) {
  return await createRequest(fields)
}

export async function signUpWithInvite({ token, email, password, name }) {
  log('signUpWithInvite: start')
  const invite = await getInvite(token)
  if (!invite) throw new Error('This invite link is invalid or has already been used.')
  const tier = invite.tier ?? 'member'

  if (!isSupabaseConfigured) {
    const users = loadDemoUsers()
    if (users.some((u) => u.email.toLowerCase() === email.trim().toLowerCase())) {
      throw new Error('An account with this email already exists.')
    }
    const created = {
      id: `demo-${Date.now()}`,
      email: email.trim(),
      password,
      full_name: name?.trim() || invite.full_name || '',
      phone: invite.phone || '',
      connection_to_shul: invite.connection_to_shul || '',
      tier,
      status: 'approved',
    }
    users.push(created)
    saveDemoUsers(users)
    await markInviteAccepted(token)
    localStorage.setItem(SESSION_KEY, created.email)
    setState({ user: publicUser(created), loading: false })
    return
  }

  // emailRedirectTo controls where Supabase's confirmation email link points.
  // Without it, Supabase falls back to the dashboard "Site URL" (which defaults
  // to http://localhost:3000). Using the live origin keeps the link on the
  // deployed domain. Land on /login (the user has already set a password here).
  const { data, error } = await supabase.auth.signUp({
    email,
    password,
    options: { emailRedirectTo: `${window.location.origin}/login` },
  })
  if (error) throw error
  const authUser = data.user
  if (authUser) {
    // Create the profile as an UNPRIVILEGED row only. The client may no longer
    // self-approve or self-assign a tier — RLS ("Users can insert own profile"
    // requires tier='member' AND status='pending') and the guard_profile_
    // escalation trigger block that. Approval + tier come from accept-invite.
    const { error: insertError } = await supabase.from('profiles').insert({
      id: authUser.id,
      email: authUser.email,
      full_name: name?.trim() || invite.full_name || '',
      phone: invite.phone || '',
      connection_to_shul: invite.connection_to_shul || '',
      tier: 'member',
      status: 'pending',
    })
    if (insertError) log('signUpWithInvite: profile insert error —', insertError.message)

    // Elevate to approved at the invite's tier SERVER-SIDE. accept-invite
    // re-validates the invite token, confirms the email matches, sets
    // status='approved' + the invite tier via the service role, and burns the
    // invite. Client-side approval/tier assignment is no longer possible.
    const { error: acceptError } = await supabase.functions.invoke('accept-invite', {
      body: { invite_token: token },
    })
    if (acceptError) {
      log('signUpWithInvite: accept-invite error —', acceptError.message)
      throw new Error('Your account was created but could not be activated. Please contact the administrator.')
    }
    // Refresh the session so the JWT/profile reflect the approved status on the
    // next fetchProfile (onAuthStateChange also fires from signUp).
    try { await supabase.auth.refreshSession() } catch { /* best-effort */ }
  }
  // Invite is marked used server-side by accept-invite (the invites table is
  // admin-only under RLS, so the client cannot mark it).
}

// ─── hook ────────────────────────────────────────────────────────────────────
export function useAuth() {
  const snap = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
  return {
    user: snap.user,
    loading: snap.loading,
    signIn,
    signOut,
    signUpWithInvite,
    requestAccess,
  }
}

