import { supabase, isSupabaseConfigured } from './supabase'
import { SEED_SHIURIM } from '../data/seed'

// Unified data access. Falls back to seed data when Supabase isn't configured,
// so the UI is fully populated in local dev without any backend.

export async function fetchShiurim() {
  if (!isSupabaseConfigured) {
    return [...SEED_SHIURIM].sort(
      (a, b) => new Date(b.date_recorded) - new Date(a.date_recorded)
    )
  }
  // Explicit high limit: Supabase caps unbounded selects at 1000 rows by
  // default. The library is already ~1000 shiurim, so without this the newest
  // rows would silently push older ones out, breaking Home/Browse category
  // filters that filter this list client-side.
  const { data, error } = await supabase
    .from('shiurim')
    .select('*')
    .eq('published', true)
    .order('date_recorded', { ascending: false })
    .limit(5000)
  if (error) throw error
  return data
}

export async function fetchShiurById(id) {
  if (!isSupabaseConfigured) {
    return SEED_SHIURIM.find((s) => s.id === id) ?? null
  }
  const { data, error } = await supabase
    .from('shiurim')
    .select('*')
    .eq('id', id)
    .single()
  if (error) throw error
  return data
}

export async function incrementPlayCount(id) {
  if (!isSupabaseConfigured) return
  // Best-effort; relies on the increment_play_count RPC from the migration.
  await supabase.rpc('increment_play_count', { shiur_id: id })
}

